-- hrm.tg_attendance_penalties_lock: No lateness penalty of a locked attendance period is added, changed or removed (FR-XM-26); refused with constraint ck_attendance_period_locked.
create or replace function hrm.tg_attendance_penalties_lock() returns trigger
language plpgsql as $fn$
declare
    v_status text;
begin
    for v_status in select p.status from hrm.attendance_periods p
                     where p.id in (case when tg_op <> 'INSERT' then old.period_id end, case when tg_op <> 'DELETE' then new.period_id end)
                     for share loop
        if v_status = 'locked' then
            raise exception 'attendance penalty of % on %: its attendance period is locked; use a retroactive adjustment (FR-XM-26)', coalesce(new.employment_id, old.employment_id), coalesce(new.work_date, old.work_date)
                using errcode = '23514', constraint = 'ck_attendance_period_locked';
        end if;
    end loop;
    return case when tg_op = 'DELETE' then old else new end;
end
