-- hrm.tg_leave_ledger_lock: No leave usage, usage reversal or encashment is dated in a locked attendance period of the employment (FR-XM-26, FR-HRM-LVE-07); entitlement postings stay possible (R-146); refused with constraint ck_attendance_period_locked.
create or replace function hrm.tg_leave_ledger_lock() returns trigger
language plpgsql as $fn$
begin
    if new.kind in ('usage', 'usage_reversal', 'encashment') and hrm.locked_attendance_period(new.employment_id, new.entry_date) is not null then
        raise exception 'leave entry of % on %: its attendance period is locked; date it in the next open period (FR-XM-26)', new.employment_id, new.entry_date
            using errcode = '23514', constraint = 'ck_attendance_period_locked';
    end if;
    return new;
end
