create trigger tg_leave_ledger_lock before insert on hrm.leave_ledger
    for each row execute function hrm.tg_leave_ledger_lock();

-- hrm.tg_attendance_adjustments_rules: An attendance adjustment keeps its facts, is never removed, targets an unlocked pay period, and only moves forward with each status added to its history (FR-XM-26, FR-XM-06); refused with constraint ck_attendance_adjustments_rules.
create or replace function hrm.tg_attendance_adjustments_rules() returns trigger
language plpgsql as $fn$
declare
    v_period hrm.attendance_periods%rowtype;
    v_keep text[] := array['status', 'status_history', 'target_pay_period_id', 'leave_reversal_id', 'workflow_instance_id', 'applied_in_run_id', 'updated_at', 'updated_by', 'row_version'];
