        raise exception 'attendance adjustment %: an adjustment is never removed', old.id
            using errcode = '23514', constraint = 'ck_attendance_adjustments_rules';
    end if;
    if new.from_date > new.to_date or length(btrim(new.reason)) = 0 or jsonb_typeof(new.status_history) <> 'array'
       or jsonb_array_length(new.status_history) = 0 or (new.status_history -> -1 ->> 'status') is distinct from new.status
       or (new.status_history -> -1 ->> 'at') is null or (new.kind = 'leave_cancellation') <> (new.leave_request_id is not null)
       or (new.status = 'applied') <> (new.applied_in_run_id is not null) then
