    if (tg_op = 'INSERT' or new.status = 'approved' and old.status <> 'approved')
       and exists (select 1 from hrm.attendance_periods t where t.company_id = new.company_id and t.pay_period_id = new.target_pay_period_id and t.status = 'locked') then
        raise exception 'attendance adjustment %: the target pay period is locked; the next open one is taken', new.id
            using errcode = '23514', constraint = 'ck_attendance_adjustments_rules';
