       or (new.leave_reversal_id is distinct from old.leave_reversal_id and not (old.leave_reversal_id is null and old.status = 'submitted' and new.status = 'approved'))
       or (new.applied_in_run_id is distinct from old.applied_in_run_id and old.applied_in_run_id is not null)
       or (new.workflow_instance_id is distinct from old.workflow_instance_id and old.workflow_instance_id is not null) then
